import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
class MentorScreen extends StatefulWidget{const MentorScreen({super.key});@override State<MentorScreen> createState()=>_MentorScreenState();}
class _MentorScreenState extends State<MentorScreen>{
 final input=TextEditingController(); String name='Aspirant',exam='Exam',language='Bengali'; double hours=3; List<String> weak=[]; final messages=<Map<String,String>>[];
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();name=p.getString('name')??'Aspirant';exam=p.getString('exam')??'Exam';language=p.getString('language')??'Bengali';hours=p.getDouble('daily_hours')??3;weak=p.getStringList('weak_subjects')??[];if(mounted)setState(()=>messages.add({'role':'mentor','text':greeting()}));}
 String greeting(){final w=weak.isEmpty?'your weakest topic':weak.first;return language=='Bengali'?name+', আমি তোমার '+exam+' preparation mentor। প্রতিদিন '+hours.toStringAsFixed(1)+' ঘণ্টা ধরে plan করব। প্রথম priority: '+w+'। আজ কী নিয়ে সাহায্য চাই?':name+', I am your '+exam+' mentor. I will plan around '+hours.toStringAsFixed(1)+' hours. First priority: '+w+'. What should we work on?';}
 String reply(String q){final s=q.toLowerCase(),w=weak.isEmpty?'GK/GS':weak.first;if(s.contains('plan')||s.contains('today')||s.contains('আজ')){final mins=(hours*60).round(),a=(hours*60*.45).round(),b=(hours*60*.35).round(),c=mins-a-b;return language=='Bengali'?'আজ: '+w+' — '+a.toString()+' মিনিট concept/PYQ, '+b.toString()+' মিনিট timed practice, '+c.toString()+' মিনিট ভুল ও revision।':'Today: '+w+' — '+a.toString()+' min concepts/PYQ, '+b.toString()+' min timed practice, '+c.toString()+' min revision.';}if(s.contains('weak')||s.contains('দুর্বল'))return language=='Bengali'?'Priority: '+(weak.isEmpty?'weak subject select করা হয়নি':weak.join(', '))+'. Mock score থেকে আরও নির্ভুল করব।':'Priority: '+(weak.isEmpty?'No weak subjects selected':weak.join(', '))+'. Mock scores will refine this.';return language=='Bengali'?'তোমার '+exam+' লক্ষ্য অনুযায়ী প্রশ্নটি ধরেছি। এখন offline mentor engine চলছে; পরের AI-service layer-এ বিস্তারিত conversational advice যোগ হবে।':'I am using your '+exam+' goal. The offline mentor engine is active; the next AI-service layer will add detailed adaptive advice.';}
 void send(){final q=input.text.trim();if(q.isEmpty)return;setState(()=>messages.add({'role':'user','text':q}));input.clear();setState(()=>messages.add({'role':'mentor','text':reply(q)}));}
 @override void dispose(){input.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,8),child:Row(children:[const CircleAvatar(child:Icon(Icons.auto_awesome_rounded)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('AI Mentor',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(exam)]))])),Expanded(child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(c,i){final m=messages[i],mine=m['role']=='user';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:330),margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(18)),child:Text(m['text']!)));})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Ask your mentor...',border:OutlineInputBorder()))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send_rounded))])))]);
}